cat > /workspace/mytests/harness.py <<'PYEOF'
"""Helper for running the project CLI on dict inputs."""
import json, subprocess, sys, os

PROJ = '/workspace/project'

def run(doc, debug=False):
    env = dict(os.environ)
    env.pop('H3ACT_DEBUG', None)
    if debug: env['H3ACT_DEBUG'] = '1'
    p = subprocess.run([sys.executable, '-B', 'main.py'], cwd=PROJ,
                       input=json.dumps(doc).encode(), stdout=subprocess.PIPE,
                       stderr=subprocess.PIPE, env=env)
    out = p.stdout.decode()
    try:
        return json.loads(out), p.returncode, p.stderr.decode()
    except Exception:
        return {'RAW': out, 'stderr': p.stderr.decode()}, p.returncode, p.stderr.decode()

def base(**kw):
    doc = {"seed": "s", "definitions": [], "timeout_ms": 10, "cases": [],
           "events": [], "channels": []}
    doc.update(kw)
    return doc

def case(name, frames, method='GET', target='/', host='h.example'):
    return {"name": name, "frames": frames,
            "expect": {"method": method, "target": target, "host": host}}

def show(doc, debug=False, keys=None):
    out, rc, err = run(doc, debug)
    print(json.dumps(out, indent=1)[:4000])
    if err.strip(): print("STDERR:", err[-2000:])
    return out
PYEOF
cd /workspace/mytests && python3 - <<'EOF'
from harness import *
# 1. timeout, no response
d = base(cases=[case('a',[{"Type":"headers","End_Stream":True,"data_to_transfered":[[":method","GET"]]}])],
         events=[])
o = show(d)
EOF
